import { describe, it, expect, beforeEach } from 'vitest';
import { BrowserGUIAgent } from '../../src/environments/local/browser/browser-gui-agent';
import { LocalBrowser } from '@agent-infra/browser';
import { ConsoleLogger } from '@tarko/mcp-agent';

describe('BrowserGUIAgent.parseAction', () => {
  let agent: BrowserGUIAgent;
  let mockBrowser: LocalBrowser;
  let mockLogger: ConsoleLogger;

  beforeEach(() => {
    mockBrowser = {
      isBrowserAlive: () => Promise.resolve(true),
      getActivePage: () => Promise.resolve({} as any),
      createPage: () => Promise.resolve({} as any),
    } as LocalBrowser;

    mockLogger = {
      info: () => {},
      warn: () => {},
      error: () => {},
      debug: () => {},
      spawn: function () {
        return this;
      },
      prefix: '',
      lastPrefixColor: '',
      level: 'info',
      colorPrefix: () => '',
      log: () => {},
      trace: () => {},
      success: () => {},
      fail: () => {},
    } as unknown as ConsoleLogger;

    agent = new BrowserGUIAgent({
      browser: mockBrowser,
      logger: mockLogger,
      factors: [1000, 1000],
    });
  });

  it('should parse click action with complete format', () => {
    const action = "click(point='<point>892 351</point>')";
    const result = (agent as any).parseAction(action);
    expect(result).toEqual({
      action_type: 'click',
      action_inputs: { start_box: '[0.892,0.351]' },
    });
  });

  it('should parse click action with missing quote', () => {
    const action = "click(point='<point>150 315</point>";
    const result = (agent as any).parseAction(action);
    expect(result).toEqual({
      action_type: 'click',
      action_inputs: { start_box: '[0.15,0.315]' },
    });
  });

  it('should parse drag action', () => {
    const action = "drag(start_point='<point>100 200</point>' end_point='<point>300 400</point>')";
    const result = (agent as any).parseAction(action);
    expect(result).toEqual({
      action_type: 'drag',
      action_inputs: {
        start_box: '[0.1,0.2]',
        end_box: '[0.3,0.4]',
      },
    });
  });

  it('should parse type action', () => {
    const action = "type(content='Hello World')";
    const result = (agent as any).parseAction(action);
    expect(result).toEqual({
      action_type: 'type',
      action_inputs: { content: 'Hello World' },
    });
  });

  it('should parse key action', () => {
    const action = "key(key='Enter')";
    const result = (agent as any).parseAction(action);
    expect(result).toEqual({
      action_type: 'key',
      action_inputs: { key: 'Enter' },
    });
  });

  it('should parse key action with missing quote', () => {
    const action = "key(key='Ctrl+C'";
    const result = (agent as any).parseAction(action);
    expect(result).toEqual({
      action_type: 'key',
      action_inputs: { key: 'Ctrl+C' },
    });
  });

  it('should parse scroll action', () => {
    const action = "scroll(direction='down')";
    const result = (agent as any).parseAction(action);
    expect(result).toEqual({
      action_type: 'scroll',
      action_inputs: { direction: 'down' },
    });
  });

  it('should parse scroll action with missing quote', () => {
    const action = "scroll(direction='up";
    const result = (agent as any).parseAction(action);
    expect(result).toEqual({
      action_type: 'scroll',
      action_inputs: { direction: 'up' },
    });
  });

  it('should handle escaped characters in type content', () => {
    const action = "type(content='Test with \\'quotes\\' and \\n newlines')";
    const result = (agent as any).parseAction(action);
    expect(result).toEqual({
      action_type: 'type',
      action_inputs: { content: "Test with 'quotes' and \n newlines" },
    });
  });

  it('should handle simple type content without complex escapes', () => {
    const action = "type(content='Simple text content')";
    const result = (agent as any).parseAction(action);
    expect(result).toEqual({
      action_type: 'type',
      action_inputs: { content: 'Simple text content' },
    });
  });

  it('should handle custom scaling factors', () => {
    const customAgent = new BrowserGUIAgent({
      browser: mockBrowser,
      logger: mockLogger,
      factors: [1920, 1080],
    });

    const action = "click(point='<point>960 540</point>')";
    const result = (customAgent as any).parseAction(action);
    expect(result).toEqual({
      action_type: 'click',
      action_inputs: { start_box: '[0.5,0.5]' },
    });
  });

  it('should handle empty action string', () => {
    const action = '';
    const result = (agent as any).parseAction(action);
    expect(result).toEqual({
      action_type: '',
      action_inputs: {},
    });
  });
});

import {
  afterEach,
  beforeEach,
  beforeAll,
  afterAll,
  describe,
  expect,
  test,
} from 'vitest';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { InMemoryTransport } from '@modelcontextprotocol/sdk/inMemory.js';
import { createServer, type GlobalConfig } from '../../src/server.js';
import express from 'express';
import { AddressInfo } from 'net';

describe('Browser Action Tests', () => {
  let client: Client;
  let app: express.Express;
  let httpServer: ReturnType<typeof app.listen>;
  let baseUrl: string;

  beforeAll(() => {
    app = express();

    // 首页 - 包含各种类型的输入元素
    app.get('/', (req, res) => {
      res.send(`
        <!DOCTYPE html>
        <html>
          <head><title>Form Input Test</title></head>
          <body>
            <h1>Form Input Test Page</h1>

            <!-- 基本输入框 -->
            <div>
              <label for="text-input">Text Input:</label>
              <input type="text" id="text-input" placeholder="Enter text" />
            </div>

            <!-- 预填充内容的输入框 -->
            <div>
              <label for="prefilled-input">Prefilled Input:</label>
              <input type="text" id="prefilled-input" value="Initial content" />
            </div>

            <!-- 密码输入框 -->
            <div>
              <label for="password-input">Password Input:</label>
              <input type="password" id="password-input" />
            </div>

            <!-- 文本区域 -->
            <div>
              <label for="textarea">Textarea:</label>
              <textarea id="textarea" rows="4" cols="50">Default textarea content</textarea>
            </div>

            <!-- 选择框 -->
            <div>
              <label for="select">Select:</label>
              <select id="select">
                <option value="option1">Option 1</option>
                <option value="option2">Option 2</option>
                <option value="option3">Option 3</option>
              </select>
            </div>

            <!-- 可编辑内容 -->
            <div>
              <label>ContentEditable Div:</label>
              <div id="contenteditable" contenteditable="true" style="border: 1px solid #ccc; padding: 10px; min-height: 50px;">
                Editable content here
              </div>
            </div>

            <!-- 数字输入 -->
            <div>
              <label for="number-input">Number Input:</label>
              <input type="number" id="number-input" min="0" max="100" />
            </div>

            <!-- 邮箱输入 -->
            <div>
              <label for="email-input">Email Input:</label>
              <input type="email" id="email-input" />
            </div>

            <!-- 隐藏输入 (测试边界情况) -->
            <input type="hidden" id="hidden-input" value="hidden" />

            <!-- 禁用输入 (测试边界情况) -->
            <input type="text" id="disabled-input" disabled value="disabled" />

            <!-- 只读输入 (测试边界情况) -->
            <input type="text" id="readonly-input" readonly value="readonly" />
          </body>
        </html>
      `);
    });

    httpServer = app.listen(0);
    const address = httpServer.address() as AddressInfo;
    baseUrl = `http://localhost:${address.port}`;
  });

  afterAll(() => {
    httpServer?.close();
  });

  beforeEach(async () => {
    client = new Client(
      {
        name: 'test client',
        version: '1.0',
      },
      {
        capabilities: {
          roots: {
            listChanged: true,
          },
        },
      },
    );

    const server = createServer({
      launchOptions: {
        headless: true,
      },
    } as GlobalConfig);

    const [clientTransport, serverTransport] =
      InMemoryTransport.createLinkedPair();

    await Promise.all([
      client.connect(clientTransport),
      server.connect(serverTransport),
    ]);
  });

  afterEach(async () => {
    try {
      await client.callTool({
        name: 'browser_close',
      });
    } catch (error) {
      console.warn('Error closing browser in afterEach:', error);
    }
    await client.close();
  }, 30000);

  describe('browser_form_input_fill', () => {
    beforeEach(async () => {
      await client.callTool({
        name: 'browser_navigate',
        arguments: { url: baseUrl },
      });
    });

    test('should fill text input by selector', async () => {
      const result = await client.callTool({
        name: 'browser_form_input_fill',
        arguments: {
          selector: '#text-input',
          value: 'Test content',
        },
      });

      expect(result.isError).toBe(false);
      expect(result.content?.[0].text).toContain('Successfully filled');
      expect(result.content?.[0].text).toContain('Test content');
    });

    test('should fill text input by index', async () => {
      // 先获取可点击元素来构建 selector map
      const elementsResult = await client.callTool({
        name: 'browser_get_clickable_elements',
      });

      expect(elementsResult.isError).toBe(false);

      // 寻找文本输入框的 index
      const elementsText = elementsResult.content?.[0].text as string;
      const lines = elementsText.split('\n');
      let textInputIndex = -1;

      for (let i = 0; i < lines.length; i++) {
        if (
          lines[i].includes('text-input') ||
          lines[i].includes('placeholder="Enter text"')
        ) {
          // 提取 index，通常在行首
          const match = lines[i].match(/^(\d+):/);
          if (match) {
            textInputIndex = parseInt(match[1]);
            break;
          }
        }
      }

      // 如果找到了对应的 index，则进行测试
      if (textInputIndex >= 0) {
        const result = await client.callTool({
          name: 'browser_form_input_fill',
          arguments: {
            index: textInputIndex,
            value: 'Test by index',
          },
        });

        expect(result.isError).toBe(false);
        expect(result.content?.[0].text).toContain('Successfully filled');
        expect(result.content?.[0].text).toContain('Test by index');
      } else {
        // 如果找不到对应的 index，跳过这个测试
        expect(true).toBe(true); // 或者使用 test.skip()
      }
    });

    test('should append text by default', async () => {
      const result = await client.callTool({
        name: 'browser_form_input_fill',
        arguments: {
          selector: '#prefilled-input',
          value: ' - Additional text',
        },
      });

      expect(result.isError).toBe(false);
      expect(result.content?.[0].text).not.toContain('cleared existing text');
    });

    test('should clear existing text when clear=true', async () => {
      const result = await client.callTool({
        name: 'browser_form_input_fill',
        arguments: {
          selector: '#prefilled-input',
          value: 'New content',
          clear: true,
        },
      });

      expect(result.isError).toBe(false);
      expect(result.content?.[0].text).toContain('cleared existing text');
      expect(result.content?.[0].text).toContain('New content');
    });

    test('should fill textarea', async () => {
      const result = await client.callTool({
        name: 'browser_form_input_fill',
        arguments: {
          selector: '#textarea',
          value: 'New textarea content',
          clear: true,
        },
      });

      expect(result.isError).toBe(false);
      expect(result.content?.[0].text).toContain('Successfully filled');
